    enonce: "<span dir=\"ltr\" class=\"expr\">ABC</span> مثلّث متقايس الضلعين قمته الرئيسية <span dir=\"ltr\" class=\"expr pt\">A</span>، حيث <span dir=\"ltr\" class=\"expr\">BC = 6.</span><br><span dir=\"ltr\" class=\"expr pt\">I</span> منتصف القطعة <span dir=\"ltr\" class=\"expr\">[BC].</span><br><svg class=\"figure\" direction=\"ltr\" viewBox=\"0 0 224 244\" width=\"224\" height=\"244\" xmlns=\"http://www.w3.org/2000/svg\"><line x1=\"39.2\" y1=\"204.8\" x2=\"184.6\" y2=\"111.9\" stroke=\"#2c3e50\" stroke-width=\"1.8\"/><line x1=\"39.2\" y1=\"204.8\" x2=\"87.7\" y2=\"39.2\" stroke=\"#2c3e50\" stroke-width=\"1.8\"/><line x1=\"184.6\" y1=\"111.9\" x2=\"87.7\" y2=\"39.2\" stroke=\"#2c3e50\" stroke-width=\"1.8\"/><line x1=\"39.2\" y1=\"204.8\" x2=\"136.1\" y2=\"75.6\" stroke=\"#2c3e50\" stroke-width=\"1.8\"/><path d=\"M 144.9 82.2 L 138.3 91.0 L 129.5 84.4\" fill=\"none\" stroke=\"#c0392b\" stroke-width=\"1.3\"/><line x1=\"157.4\" y1=\"97.7\" x2=\"163.4\" y2=\"89.7\" stroke=\"#c0392b\" stroke-width=\"1.3\"/><line x1=\"108.9\" y1=\"61.4\" x2=\"114.9\" y2=\"53.4\" stroke=\"#c0392b\" stroke-width=\"1.3\"/><circle cx=\"184.6\" cy=\"111.9\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"197.6\" y=\"116.6\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">B</text><circle cx=\"87.7\" cy=\"39.2\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"83.3\" y=\"31.0\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">C</text><circle cx=\"136.1\" cy=\"75.6\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"143.9\" y=\"69.2\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">I</text><circle cx=\"39.2\" cy=\"204.8\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"31.4\" y=\"219.2\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">A</text></svg><br>برهن أنّ<span dir=\"ltr\" class=\"expr\">: (AI)</span> هو الموسط العمودي للقطعة <span dir=\"ltr\" class=\"expr\">[BC]</span>",
    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr\">AB = AC</span>  و  <span dir=\"ltr\" class=\"expr pt\">I</span> هو منتصف القطعة <span dir=\"ltr\" class=\"expr\">[BC]</span>"},{"quoi":"الاختيار","math":"المطلوب : إثبات أنّ <span dir=\"ltr\" class=\"expr\">(AI)</span> هو الموسط العمودي. نختار المنتصف متساوي البعد لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr\">: I</span> هو منتصف القطعة <span dir=\"ltr\" class=\"expr\">[BC].</span> و لماذا لا عموديان على نفس المستقيم ؟ لأنّها تحتاج مستقيمين عموديين على نفس المستقيم، و لا نملك إلّا تعامدا واحدا على الأكثر."},{"quoi":"القاعدة","math":"منتصف قطعة متساوي البعد عن طرفيها"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">I</span> هو منتصف القطعة <span dir=\"ltr\" class=\"expr\">[BC]</span>  إذن  <span dir=\"ltr\" class=\"expr\">IB = IC</span>"},{"quoi":"القاعدة","math":"المستقيم المارّ من نقطتين متساويتي البعد عن طرفي قطعة هو موسطها العمودي"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr\">AB = AC</span>  و  <span dir=\"ltr\" class=\"expr\">A ∈ (AI)</span>  و  <span dir=\"ltr\" class=\"expr\">IB = IC</span>  و  <span dir=\"ltr\" class=\"expr\">I ∈ (AI)</span>  إذن  <span dir=\"ltr\" class=\"expr\">(AI)</span> هو الموسط العمودي للقطعة <span dir=\"ltr\" class=\"expr\">[BC]</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">(AI)</span> هو الموسط العمودي للقطعة <span dir=\"ltr\" class=\"expr\">[BC]</span>"}],
    indice: "نقطتان متساويتا البعد عن B و C تكفيان لتحديد الموسط العمودي",
